//! Generate the board's constants from board.json and the machine
//! description it names (ferriboot-qemu/chips/mps2-an385.json).
use std::path::Path;

use ferriboot_build::{read_board, write_out};

/// The values this board decides. Everything else is a machine fact.
const BOARD_KEYS: &[&str] = &["BOOTLOADER_SIZE", "SLOT_SIZE", "SCRATCH_SIZE"];

fn main() {
    let board = read_board(Path::new("board.json"), BOARD_KEYS);
    assert_eq!(board.chip, "mps2-an385", "this is a QEMU mps2-an385 board");
    let mut rust = String::from(
        "// @generated by boards/qemu/layout/build.rs from board.json and its machine.\n",
    );
    rust.push_str(&board.rust_consts_with_types(&[("BOOT_INFO_SIZE", "usize")]));
    write_out("layout.rs", rust);
}
